/* nd_rec.h: record-mode form of the gSP and gDP macros (plan_s10_path CORE-1, decision D2). A file opts in with -include nd_rec.h (CMake).
 * A leaf whose pkt is in the main list (gDisplayContext->mainGfx) writes no words: the op is not decoded (nd_rec_leaf) and its slots
 * are not written. CORE-2 gives those slots a record, so a file opts in only from CORE-2 on (the walker has no record yet).
 * Any other pkt writes the words and decodes them as the bridge (nd_gbi.h) does. pkt is evaluated once.
 * nd_rec_leaf.h is generated by 3ds/tools/gen_nd_gbi.py (gen_nd_gbi.sh). The bridge leaves (nd_gbi.h) stay the form of the other files. */
#ifndef ND_REC_H
#define ND_REC_H

#include "nd_gbi.h"

/* 1 when the slot is in the main list buffer (the list gbi_task walks). Expanded at the use site (gDisplayContext is a game global). */
#define ND_IN_MAIN(p) ((const void*)(p) >= (const void*)gDisplayContext->mainGfx && (const void*)(p) < (const void*)(gDisplayContext->mainGfx + sizeof gDisplayContext->mainGfx / sizeof(Gfx)))

/* One leaf: nops ops decoded from w (the bridge count), nslots 8-byte slots (the bridge writes these at at when in_main is 0). */
void nd_rec_leaf(void* at, const void* w, unsigned nops, unsigned nslots, int in_main);

#include "nd_rec_leaf.h"

#endif
